use std::{collections::BTreeMap,fs};fn main(){let mut rows=BTreeMap::new();for l in fs::read_to_string("research/hec_residual_span_20261116/shared-interpolation-strong/CONTROL.tsv").unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();assert_eq!(v.len(),7);let n=|j:usize|v[j].parse::<u64>().unwrap();let k=(n(0),n(1),n(2),n(3));let c:Vec<u64>=v[6].split(',').map(|x|x.parse().unwrap()).collect();assert_eq!(c.len(),16);assert_eq!(c[8],2*c[7]+c[5]+c[6]);let value=(n(4),n(5),c);if k.2==1{assert_eq!(rows[&(k.0,k.1,0,k.3)],value)}assert!(rows.insert(k,value).is_none());}assert_eq!(rows.len(),20);println!("p\tsm\tsplit\treference_REDC\tshared_REDC\treference_over_shared_REDC\treference_inv\tshared_inv\treference_over_shared_inv");for(&(p,sm,rep,arm),(_,split,a))in &rows{if rep!=0||arm!=0{continue}let(_,b_split,b)=&rows[&(p,sm,0,1)];assert_eq!(split,b_split);println!("{p}\t{sm}\t{split}\t{}\t{}\t{:.6}\t{}\t{}\t{:.6}",a[8],b[8],a[8]as f64/b[8]as f64,a[9],b[9],a[9]as f64/b[9]as f64);}eprintln!("calls=20 all_repeats_and_REDC_identity=true all_split_counts_equal=true no_complete_solve_claim=true");}
